import{_ as r,o as i,c as t,ag as a}from"./chunks/framework.BPmc_f4o.js";const v=JSON.parse('{"title":"Driver SDK Reference","description":"Build device drivers for Muxit — JavaScript modules or C# class libraries.","frontmatter":{"title":"Driver SDK Reference","description":"Build device drivers for Muxit — JavaScript modules or C# class libraries."},"headers":[],"relativePath":"reference/driver-sdk.md","filePath":"reference/driver-sdk.md"}'),s={name:"reference/driver-sdk.md"};function d(o,e,n,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="driver-sdk-reference" tabindex="-1">Driver SDK Reference <a class="header-anchor" href="#driver-sdk-reference" aria-label="Permalink to &quot;Driver SDK Reference&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Most devices don&#39;t need a custom driver — start here first</p><p>If your device speaks <strong>SCPI</strong>, prints <strong>text lines</strong> (<code>TEMP: 25.5</code>), or emits <strong>fixed binary frames</strong> (Modbus etc.), you don&#39;t write a driver at all. You write a short connector config that picks a built-in <a href="./concepts.html">Protocol</a> (<code>Scpi</code> / <code>LineText</code> / <code>BinaryStream</code>) and declares a <code>schema:</code> block — and the <a href="./../guides/protocol-authoring.html">AI assistant</a> can draft and test it against your hardware in about a minute. See <a href="./concepts.html">Driver, Protocol, Engine</a> to pick the right path.</p><p><strong>Reach for the Driver SDK only when a Protocol can&#39;t express your device</strong> — a vendor SDK or native library (spectrometers, robots), a Python-only instrument stack (numpy / pyvisa / vendor wheels), or a device with quirky multi-step logic that doesn&#39;t fit a generic wire parser. It&#39;s the escape hatch, not the front door.</p></div><p>Build device drivers for Muxit as standalone .NET class libraries (Tier 3), Python modules (Tier 2), or JavaScript modules (Tier 1). C# drivers implement <code>IConnectorDriver</code> from the shared SDK. JS drivers export a default object with <code>meta</code>, <code>init</code>, <code>get</code>, <code>set</code>, <code>execute</code>, and <code>shutdown</code> methods. Python drivers subclass <code>muxit_driver.Driver</code> and call <code>run(...)</code>.</p><h2 id="driver-tiers" tabindex="-1">Driver Tiers <a class="header-anchor" href="#driver-tiers" aria-label="Permalink to &quot;Driver Tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Type</th><th>Location</th><th>Status</th><th>Docs</th></tr></thead><tbody><tr><td>0</td><td>Built-in (C#)</td><td>Compiled into MuxitServer</td><td>Always available</td><td><a href="/reference/drivers/">Built-in Drivers</a></td></tr><tr><td>1</td><td>JavaScript</td><td><code>workspace/drivers/*.muxdriver</code> (or loose <code>*.driver.js</code>)</td><td>Active (sandboxed V8)</td><td><a href="./driver-sdk-js.html">JS Driver SDK</a></td></tr><tr><td>2</td><td>Python</td><td><code>workspace/drivers/*.muxdriver</code> (or loose <code>*.driver.py</code>)</td><td>Active (subprocess + JSON-RPC)</td><td><a href="./driver-sdk-python.html">Python Driver SDK</a></td></tr><tr><td>3</td><td>DLL Extension (C#)</td><td><code>workspace/drivers/*.muxdriver</code></td><td>Active</td><td><a href="./driver-sdk-csharp.html">C# Driver SDK</a></td></tr></tbody></table><p>Choose your SDK based on what you&#39;re building:</p><ul><li><strong><a href="./driver-sdk-js.html">JS Driver SDK</a></strong> — quick to write, sandboxed V8, good for serial/TCP instruments</li><li><strong><a href="./driver-sdk-python.html">Python Driver SDK</a></strong> — for Python-only ecosystems (numpy, torch, transformers, instrument SDKs); subprocess-isolated</li><li><strong><a href="./driver-sdk-csharp.html">C# Driver SDK</a></strong> — full .NET power, NuGet packages, good for complex hardware with native libraries</li></ul><h2 id="documenting-properties-and-actions" tabindex="-1">Documenting properties and actions <a class="header-anchor" href="#documenting-properties-and-actions" aria-label="Permalink to &quot;Documenting properties and actions&quot;">​</a></h2><p>Every property and action accepts two doc fields regardless of tier:</p><ul><li><code>description</code> — one-line summary. Always visible (AI system prompt, IntelliSense, driver doc page).</li><li><code>details</code> — short markdown with parameter enums, side effects, failure modes, non-obvious invariants. Surfaced on-demand in the driver doc page (collapsible panel), in the script editor&#39;s hover popup, and in the full schema that the AI fetches via <code>get_connector_schema</code> / <code>get_driver_schema</code>. <strong>Never</strong> included in the upfront AI system prompt — use <code>details</code> freely for anything that would otherwise cost the user or an AI agent a round-trip of trial and error.</li></ul><p>See the per-tier docs for syntax: <a href="./driver-sdk-js.html#property-and-action-descriptions">JS Driver SDK</a>, <a href="./driver-sdk-csharp.html#description-vs-details">C# Driver SDK</a>.</p><h2 id="manifest-validation" tabindex="-1">Manifest &amp; validation <a class="header-anchor" href="#manifest-validation" aria-label="Permalink to &quot;Manifest &amp; validation&quot;">​</a></h2><p>Every driver ships a <code>manifest.json</code>. See:</p><ul><li><strong><a href="./driver-manifest.html">Driver Manifest Schema</a></strong> — required and optional fields, premium integrity rules, complete examples</li><li><strong><a href="./driver-tags.html">Driver Tags</a></strong> — controlled tag vocabulary</li><li><strong><a href="./driver-validation.html">Driver Validation</a></strong> — rules enforced by <code>node drivers.js validate</code>, severities, JSON output</li></ul><h2 id="packaging-distribution" tabindex="-1">Packaging &amp; Distribution <a class="header-anchor" href="#packaging-distribution" aria-label="Permalink to &quot;Packaging &amp; Distribution&quot;">​</a></h2><p>Drivers can be packaged as <code>.muxdriver</code> files (ZIP archives with a <code>manifest.json</code>) for sharing through the <a href="/guides/driver-marketplace.html">Driver Marketplace</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Interactive Driver Manager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Scaffold a new driver</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Build + package every driver → dist/drivers/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Package a single driver interactively</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # View package contents</span></span></code></pre></div><p>See the <a href="/guides/driver-marketplace.html">Driver Marketplace guide</a> for the full packaging and publishing workflow.</p>`,18)])])}const u=r(s,[["render",d]]);export{v as __pageData,u as default};
